import{_ as n,C as r,o,c as h,j as t,a as d,E as s,a5 as i}from"./chunks/framework.-jms6n7v.js";const b=JSON.parse('{"title":"Performance","description":"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same…","frontmatter":{"title":"Performance","order":3,"aside":false,"pageClass":"performance-page","prev":{"text":"Comparison","link":"/compare"},"next":{"text":"Migration","link":"/migration/"}},"headers":[{"level":2,"title":"What is measured","slug":"what-is-measured","link":"#what-is-measured","children":[]},{"level":2,"title":"How it is kept fair","slug":"how-it-is-kept-fair","link":"#how-it-is-kept-fair","children":[]},{"level":2,"title":"Next to Realm","slug":"next-to-realm","link":"#next-to-realm","children":[]},{"level":2,"title":"Where DaruDB is behind, and why","slug":"where-darudb-is-behind-and-why","link":"#where-darudb-is-behind-and-why","children":[]},{"level":2,"title":"The complex suite","slug":"the-complex-suite","link":"#the-complex-suite","children":[{"level":3,"title":"What it measures","slug":"what-it-measures","link":"#what-it-measures","children":[]},{"level":3,"title":"Where DaruDB is behind in the complex suite","slug":"where-darudb-is-behind-in-the-complex-suite","link":"#where-darudb-is-behind-in-the-complex-suite","children":[]}]},{"level":2,"title":"Run it yourself","slug":"run-it-yourself","link":"#run-it-yourself","children":[]}],"relativePath":"performance.md","filePath":"en/performance.md","lastUpdated":1793191173000}'),l={name:"performance.md"};function u(c,e,m,p,f,g){const a=r("PerformanceTable");return o(),h("div",null,[e[0]||(e[0]=t("h1",{id:"performance",tabindex:"-1"},[d("Performance "),t("a",{class:"header-anchor",href:"#performance","aria-label":'Permalink to "Performance"'},"​")],-1)),e[1]||(e[1]=t("p",null,"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same objects and workloads in every database, at the same durability settings, on one machine.",-1)),e[2]||(e[2]=t("p",null,"The table follows the language chosen in the sidebar. The stores of one language ran on one machine one after another, so their times compare with each other; the tables of different languages come from different runs and do not.",-1)),s(a),e[3]||(e[3]=i('<h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><p>One collection of 100,000 objects, each with a name, an email under a unique index, an age under an index, a city and a score, both without an index. Every row times many operations and divides by their number:</p><table tabindex="0"><thead><tr><th>Workload</th><th>What it does</th></tr></thead><tbody><tr><td>Insert, one object per sync commit</td><td>500 commits of one object, each waiting for the disk</td></tr><tr><td>Insert, one object per deferred commit</td><td>10,000 commits of one object, each leaving the sync for later</td></tr><tr><td>Insert 100,000 objects in one transaction</td><td>Every object, the commit included</td></tr><tr><td>Get by primary key, random order</td><td>100,000 reads of one object</td></tr><tr><td>Get by a unique index, random order</td><td>20,000 reads of one object through the email</td></tr><tr><td>Query an indexed value, 1,250 objects</td><td>The objects of one age</td></tr><tr><td>Query an indexed range, sorted, first 20</td><td>The first 20 objects of five ages, sorted by age descending, then by key</td></tr><tr><td>Count through an index</td><td>The objects with an age of 40 or more</td></tr><tr><td>Query without an index, 1,000 objects</td><td>The objects of one city, ten times over</td></tr><tr><td>Query without an index, 1,000 objects, first run</td><td>The first of those ten</td></tr><tr><td>Top 10 by a field without an index</td><td>The 10 objects with the highest score, ten times over</td></tr><tr><td>Top 10 by a field without an index, first run</td><td>The first of those ten</td></tr><tr><td>Read and update 10,000 objects</td><td>Each read, given a new age and written back, in one transaction with its commit</td></tr><tr><td>Delete 10,000 objects</td><td>In one transaction with its commit</td></tr></tbody></table><p>The two queries without an index each have a row of their own for their first run, since DaruDB answers such a query faster once it has run: it remembers where the field it tests or sorts by lies in each record it read, and reads it there the next time. A query that an application runs once takes the time of the first run.</p><p>Every database is used the way an application in that language would use it. DaruDB runs through its public API with a schema, SQLite through SQL with prepared statements, and the key-value stores keep a record and the indexes an application would write for them. Every read is made into an object of the language with all its fields, and a query that runs many times is prepared once. An update sets the one field it changes, as SQL sets one column: through Node.js, Python and Dart with <code>update</code>, where writing the whole object back would build it again in the language first, and through Rust with <code>TypedWriter::set</code>, which names the field through the type.</p><p>The Node.js and Dart tables also have Realm, for applications moving from it, though its vendor deprecated it in September 2024 and ended support in September 2025; the <a href="./migration/realm">migration guide</a> shows how to move the data. Realm assigns no keys, so the application gives each object the key the other stores assign. It has no unique index besides the primary key, so the email has a plain index, and its queries are strings it parses on every call, since it has no prepared queries. An update sets the one property.</p><h2 id="how-it-is-kept-fair" tabindex="-1">How it is kept fair <a class="header-anchor" href="#how-it-is-kept-fair" aria-label="Permalink to &quot;How it is kept fair&quot;">​</a></h2><ul><li><strong>The same durability.</strong> A sync commit waits until the disk has it: DaruDB&#39;s default commit, SQLite&#39;s write-ahead log with <code>synchronous = FULL</code>, LMDB&#39;s default commit, redb&#39;s <code>Durability::Immediate</code>, Hive&#39;s write followed by <code>flush</code>, and Realm&#39;s commit. A deferred commit returns before that: DaruDB&#39;s deferred commit, <code>synchronous = NORMAL</code>, LMDB&#39;s <code>NO_SYNC</code>, redb&#39;s <code>Durability::None</code> and Hive&#39;s write alone. Realm has no commit that leaves the sync for later, so its cell in that row is empty. redb&#39;s promises less than the others, since nothing it writes is durable until a later immediate commit.</li><li><strong>The same work.</strong> Every row hashes the keys and ages of what it found, in the order it found them, and a run in which two databases disagree fails rather than giving a time.</li><li><strong>A clean start.</strong> Each pass of each database runs in a process of its own, on new files, and the databases take turns in an order that changes every run. A time is the median of the runs.</li><li><strong>The same machine.</strong> The databases of one language run on one machine, one after another.</li></ul><p>The cache each database may use is left at its default, apart from SQLite&#39;s, which is raised to DaruDB&#39;s 32 MiB. A database that keeps every object in memory, as Hive does, reads without touching its file.</p><p>The tables come from the <code>run-benchmarks</code> workflow, which runs each language on a GitHub-hosted Linux runner of its own. Those runners mount their disk without write barriers, so a sync commit there waits for the file system&#39;s work but not for the disk&#39;s own cache. They also differ in processor and disk from one run to the next, and the commit rows move most with them: through Node.js, a deferred commit of one object took SQLite 53 µs and DaruDB 25 µs on the EPYC 9V45 runner of one run, and 33 µs and 46 µs on the EPYC 7763 runner of the next, on the same day and the same code. The next section says why. Compare a commit row&#39;s databases within one table only.</p><h2 id="next-to-realm" tabindex="-1">Next to Realm <a class="header-anchor" href="#next-to-realm" aria-label="Permalink to &quot;Next to Realm&quot;">​</a></h2><p>For an application moving from Realm, the Node.js and Dart tables are the ones to read; choose Node.js or Dart in the sidebar to see them. DaruDB is ahead of Realm in every row but the first run of the query of one city, a field without an index, and in Dart the update as well. Realm keeps each property&#39;s values together and reads only the city, and takes 0.69 times DaruDB&#39;s time on the first run in Node.js and 0.73 times in Dart; over ten runs it takes 1.04 and 1.10 times, since from the second run on DaruDB reads the city where the first found it in each record. In Node.js and in Dart, Realm takes 2.2 and 3.2 times as long for a sync commit and has no deferred one, 6.4 and 3.4 times as long to insert 100,000 objects in one transaction, and 6.3 and 2.2 times to delete 10,000. It takes 3.8 and 2.5 times as long to read by key, and 13 and 7.3 times through the email, since it parses a query string on every call and has no unique index besides the primary key. It takes 4.6 and 3.8 times as long for the objects of one age, 112 and 98 times for the first 20 of five ages, since it sorts every object of the five ages before it takes the first 20, and 2.4 to 3.7 times for the ten objects with the highest score. An update sets one field in both, and takes Realm 1.11 times DaruDB&#39;s time in Node.js and 0.50 times in Dart.</p><h2 id="where-darudb-is-behind-and-why" tabindex="-1">Where DaruDB is behind, and why <a class="header-anchor" href="#where-darudb-is-behind-and-why" aria-label="Permalink to &quot;Where DaruDB is behind, and why&quot;">​</a></h2><p>In this run Rust, Dart and Python ran on runners with AMD EPYC 9V45 processors, and Node.js on one with an AMD EPYC 7763. DaruDB is ahead of every other database in most rows in Node.js, Dart and Python, and in Python ahead of SQLite in every row but the first runs of the queries without an index. In Dart it is ahead in every row but the read by key and the queries without an index, where Hive, which keeps every object in memory, is ahead, and the update, where Realm is. In Rust, LMDB is ahead in the deferred commit, the reads and the queries but the count, and redb and SQLite in the queries through the age index and the first runs of those without one. These are the rows where DaruDB is not ahead, with what makes each slower:</p><ul><li><strong>A deferred commit of one object.</strong> LMDB is ahead in every language it runs in, taking 0.36 to 0.51 times DaruDB&#39;s time, redb in Rust, taking 0.72 times, and SQLite in Node.js, taking 0.73 times. On Linux, about half of DaruDB&#39;s commit is spent in the kernel: it makes about fourteen system calls, ten writes for the eleven or so pages it writes and four to take and release the writer lock and to check for other writers and readers, since processes coordinate through file locks alone. LMDB makes seven writes and coordinates processes through a mutex in shared memory, which DaruDB rejects: a process that dies holding one can leave the others stuck. SQLite&#39;s deferred commits are not all of its work: it syncs its log and its file at each checkpoint of the log, every thousand pages, and on most runners its deferred commits spent two thirds of their time or more waiting for those syncs. The EPYC 7763 runners finish them sooner, and their processor, the oldest of the runner kinds, is the slowest at DaruDB&#39;s commit, which waits for nothing. In Rust, Dart and Python, on EPYC 9V45 runners, DaruDB&#39;s deferred commit took 0.42 to 0.44 times SQLite&#39;s time.</li><li><strong>Sync commits</strong> move from runner to runner more than any other row. In this run SQLite takes 0.85 times DaruDB&#39;s time in Node.js, on an EPYC 7763 runner, while in Rust, Dart and Python, on EPYC 9V45 runners, DaruDB is ahead of every other database. On the runners, a sync commit is mostly the file system&#39;s work. DaruDB writes a commit&#39;s pages where the free pages are, scattered over the file, where SQLite appends its pages to its log, and on the EPYC 7763 runners syncing twelve pages written scattered over a file took three times as long as syncing the same twelve written in one run, in a probe of the disk alone.</li><li><strong>Reads and queries through an index, in Rust.</strong> LMDB finds an object by its key in 0.68 times DaruDB&#39;s time and redb in 0.83 times, LMDB finds one by its email in 0.72 times, and LMDB, redb and SQLite run the queries through the age index in 0.48 to 0.82 times. A DaruDB lookup finds each page below the root in its page cache, under a lock and with a reference count, which takes a larger share of a lookup on these x86 processors than on Apple&#39;s, then searches the node comparing keys as bytes, and decodes the record, which tags each field with an id, into the struct. LMDB reads its file through a memory map, with no cache to look in, redb compares its primary keys as integers, and both read the record written by hand for them, with its fields at fixed places. DaruDB does not map its file, because another process can change mapped bytes under a reader, and a mapping does not mix with encryption. The sorted range costs more besides: it sorts by age descending and then by key, so DaruDB walks the age index backwards and holds back the objects of each age to give them in key order, where the loop written for the key-value stores asks for each age in turn. On an Apple M1 Max, DaruDB was ahead of LMDB in these rows but the sorted range.</li><li><strong>A read by key in Dart</strong>, where Hive takes 0.90 times DaruDB&#39;s time. Hive keeps every object of a box in memory and gives the one it holds, where DaruDB finds the record in its tree, through the page cache, and makes the object from it.</li><li><strong>Queries without an index.</strong> LMDB in Rust scans 2.6 to 7.1 times as fast, Hive in Dart 1.1 to 2.4 times, and Realm finds the objects of one city faster on the first run, in Node.js and in Dart. SQLite and redb are ahead on the first run alone: SQLite takes 0.78 to 0.96 times DaruDB&#39;s time in Rust, Node.js, Dart and Python, where it is level on the query of the highest scores, and redb 0.93 and 0.98 times in Rust. Over ten runs DaruDB is ahead of both, which take 1.20 to 1.54 times its time, and of Realm, which takes 1.04 to 3.7 times. The record written by hand for the key-value stores keeps the age and the score at fixed places, so a scan reads those bytes and decodes only what it returns; Realm keeps each property&#39;s values together, so a scan reads only the city; and SQLite&#39;s record lists the types of its columns at its start, so finding one column adds up the sizes before it without reading them. A DaruDB record tags each field with an id and a type, which makes renaming a field free and lets the engine check what it reads from a file it does not trust, so a first scan steps over the fields before the one it tests in each record. It remembers where it found the field, and the runs after the first read it there.</li><li><strong>An update in Dart</strong>, where Realm takes 0.50 times DaruDB&#39;s time, and 1.11 times in Node.js. Realm keeps each property&#39;s values together, so setting the age changes that value alone, where DaruDB writes the object&#39;s record again with the new age.</li><li><strong>A lookup through a unique index in Node.js and Python</strong>, where SQLite takes 0.89 times DaruDB&#39;s time in Node.js and LMDB 0.96 times in Python: two lookups make it, the email&#39;s entry in the index and then the object by its key, and making the object from its record in the language takes a share of it, a fifth in JavaScript.</li></ul><h2 id="the-complex-suite" tabindex="-1">The complex suite <a class="header-anchor" href="#the-complex-suite" aria-label="Permalink to &quot;The complex suite&quot;">​</a></h2><p>A second suite measures an application with more than one collection: three collections that link to each other, 401,000 objects in all, and queries through links, lists and several indexes at once. Only the stores with a query language run it, DaruDB, SQLite and, in Node.js and Dart, Realm: a key-value store has no planner, and the code written by hand for each query would be what a row measured, not the store.</p><p>These tables come from the same run as the ones above, each language on the runner it ran the first suite on, so Rust, Dart and Python ran on EPYC 9V45 runners and Node.js on an EPYC 7763. Each cell is the median of five passes, since a pass takes longer here.</p>',18)),s(a,{suite:"complex"}),e[4]||(e[4]=i(`<h3 id="what-it-measures" tabindex="-1">What it measures <a class="header-anchor" href="#what-it-measures" aria-label="Permalink to &quot;What it measures&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Collection</th><th>Objects</th><th>Fields</th></tr></thead><tbody><tr><td>Organizations</td><td>1,000</td><td>A code as the key, a name, a kind and a country, both indexed, and a year</td></tr><tr><td>People</td><td>100,000</td><td>A name, an email under a unique index, an age, a country and a date joined, each indexed, an embedded address, a score, whether active, a link to an organization, indexed, and a list of one to three tags, indexed</td></tr><tr><td>Posts</td><td>300,000</td><td>A link to the author, indexed, a title, a body of twelve words, likes, a language and a date, each indexed, whether pinned, and a list of up to two tags, indexed</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Workload</th><th>What it does</th></tr></thead><tbody><tr><td>Load 401,000 objects, 10,000 to a transaction</td><td>The three collections, each commit waiting for the disk; the time is per object</td></tr><tr><td>A person, their organization and their 5 newest posts</td><td>By key, then through the link, then through the posts&#39; author index, 10,000 times</td></tr><tr><td>Three conditions on two indexes, sorted, first 50</td><td>An age range of ten years, one country and active, by score descending</td></tr><tr><td>Count with OR across two indexes</td><td>The people of two countries, or aged 78 and over</td></tr><tr><td>Names that start with a text</td><td>The people whose name starts with <code>person</code> and a number below 1,000, a field without an index</td></tr><tr><td>A page of 50, deep in an indexed order</td><td>50 people in the order they joined, after skipping up to 98,703</td></tr><tr><td>Through a link</td><td>The 20 newest posts with 900 likes or more whose author lives in one country</td></tr><tr><td>Through two links</td><td>Counting the posts of one language whose author&#39;s organization is of one kind</td></tr><tr><td>A tag in a list, sorted by another index</td><td>The 20 posts with one tag that have the most likes</td></tr><tr><td>Count posts whose text contains a phrase</td><td>Two words in a row, in the body of 300,000 posts, without an index</td></tr><tr><td>Count with conditions on two indexes</td><td>The posts of one language with 500 likes or more</td></tr><tr><td>Update the people a query finds</td><td>Adding a year to the age of everyone in four countries, about 20,000 people, in one transaction; the time is per person</td></tr><tr><td>Delete 1,000 people with their posts</td><td>In one transaction; the time is per person</td></tr></tbody></table><p>Each store writes its queries the way an application would: DaruDB in its query language, prepared once; SQLite in SQL, with a join or a subquery for a link and a table of tags for each list; Realm in its query language, with a backlink for a person&#39;s posts, since Realm cannot index a link. An update through SQL is one <code>UPDATE</code> statement, where DaruDB and Realm find the people and change each. Every row digests what it found, and a run in which two stores disagree fails, as in the suite above.</p><h3 id="where-darudb-is-behind-in-the-complex-suite" tabindex="-1">Where DaruDB is behind in the complex suite <a class="header-anchor" href="#where-darudb-is-behind-in-the-complex-suite" aria-label="Permalink to &quot;Where DaruDB is behind in the complex suite&quot;">​</a></h3><p>DaruDB is ahead of SQLite in every row but the update, where SQLite takes 0.68 to 0.86 times DaruDB&#39;s time in Python, Node.js and Dart, and the two are level in Rust. Realm is ahead in four rows in Node.js and three in Dart:</p><ul><li><strong>Counting posts by a phrase in their text, and by conditions on two indexes.</strong> Realm takes 0.44 and 0.68 times DaruDB&#39;s time in Node.js, and 0.53 and 0.69 times in Dart. Realm keeps each property&#39;s values together, so it reads only the bodies, or only the languages and the likes, and counts them without making an object. DaruDB reads each post&#39;s record to find the body in it, and the records of 300,000 posts outgrow its page cache of 32 MiB, so each count reads them from the file again; with a cache that held the file, the count took half the time on an Apple M1 Max. For the count by two conditions it gathers the keys of one condition from its index, then walks the other&#39;s index for those among them.</li><li><strong>Updating the people a query finds.</strong> Realm takes 0.66 times DaruDB&#39;s time in Node.js, and 1.14 times in Dart, and SQLite 0.68 to 0.86 times outside Rust. Realm sets one value where it keeps the ages, and SQLite&#39;s one statement changes every row inside the engine. DaruDB finds the people through the country index and changes each one&#39;s record where it lies, with its entries in the age index, 6.3 to 9.5 µs a person.</li><li><strong>Posts through a link, in Dart.</strong> Realm takes 0.94 times DaruDB&#39;s time in Dart, and 1.61 times in Node.js, where making a JavaScript object of each post it finds costs more. Realm tests the likes and each author&#39;s country in the values it keeps together. DaruDB gathers the keys of the country&#39;s people from its index, follows them to their posts through the author index, meets those with the likes, and walks the date index for the newest.</li><li><strong>Deleting people with their posts, in Node.js.</strong> Realm takes 0.84 times DaruDB&#39;s time in Node.js, on an EPYC 7763 runner, and 1.46 times in Dart, on an EPYC 9V45. DaruDB deletes each post&#39;s record with its entries in five indexes, and its commit syncs the pages it changed, scattered over the file, which the EPYC 7763 runners sync more slowly, as the sync commits above show.</li></ul><h2 id="run-it-yourself" tabindex="-1">Run it yourself <a class="header-anchor" href="#run-it-yourself" aria-label="Permalink to &quot;Run it yourself&quot;">​</a></h2><p>The harness is in <a href="https://github.com/jooy2/darudb/tree/main/bench" target="_blank" rel="noreferrer"><code>bench/</code></a> of the repository, with a README that lists every setting. The <code>run-benchmarks</code> workflow runs it on GitHub-hosted runners and opens a pull request with the results for this page.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/rust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/run.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/results/rust.json</span></span></code></pre></div><p><code>--suite complex</code> runs the complex suite: <code>node bench/run.mjs rust --suite complex --runs 9 --out bench/results/rust-complex.json</code>.</p>`,11))])}const y=n(l,[["render",u]]);export{b as __pageData,y as default};
